// ICSE 10 Mathematics ch12 Section and Mid-Point Formulae — practice bank with independent re-solve checks.
// Keys and option values are typed as literals; each check recomputes them with sect.mjs in exact fractions:
// every division point by the section formula AND as A + t(B - A) (collinear, between A and B, distance ratio);
// every ratio from one coordinate, checked with the other and by recomputing the point; every axis or line cut
// with the point checked on the axis or line; every mid-point as the 1 : 1 point; every centroid as the 2 : 1
// point of all three medians; every missing vertex or end point checked forwards. Every typed working line in a
// solution or model answer is parsed and checked by work.mjs, and MCQ distractors are recomputed from the slip
// they represent.
import { Q, mk, r } from './lib.mjs';
import { pt, same, is, section, ratioOf, cutAt, axisCut, lineCut, mid, otherEnd, centroid, thirdVertex, fourthVertex, fromMidpoints, dist, dist2, collinear, between, ct, rt, secLine, midLine, centLine, endLine, thirdLine, fourthLine, F, Fr } from './sect.mjs';
import { steps, ARITH, eqctx, solvectx } from './work.mjs';

const J = (lines) => lines.join('\n\n');
const A = (lines) => steps(ARITH, lines);
const W = (ctx, lines) => steps(ctx, lines);
const p = pt;
/** Coordinate-pair options. */
const co = (ps) => ps.map((q) => `$${ct(q)}$`);
/** Exactly one option is the computed point. */
const whichPt = (C, opts, target) => C.which(opts.map(ct), ct(target));
/** Ratio options. */
const ro = (rs) => rs.map((x) => `$${rt(x)}$`);
const whichR = (C, opts, target) => C.which(opts.map(rt), rt(target));
/** Equation in the ratio unknown k (AP : PB = k : 1) with its verified value. */
const K = (v, lines) => W(eqctx('k', [Fr.of(v)]), lines);
/** Signed area test: G strictly inside triangle ABC. */
const cr = (o, a, b) => a[0].sub(o[0]).mul(b[1].sub(o[1])).sub(a[1].sub(o[1]).mul(b[0].sub(o[0])));
const inside = ([a, b, c], g) => { const s = [cr(a, b, g), cr(b, c, g), cr(c, a, g)].map((v) => v.sign()); return s.every((v) => v !== 0 && v === s[0]); };

// =============================================================== MCQ
const t01 = [[-5, 5, 2, 3], [1, 9, 1, 3], [4, -8, 3, 2], [0, 7, 5, 1]];
const f01 = [(x1, x2, m, n) => (m * x2 + n * x1) / (m + n), (x1, x2, m, n) => (m * x1 + n * x2) / (m + n), (x1, x2, m, n) => (m * x2 + n * x1) / (m * n), (x1, x2, m, n) => (x1 + x2) / (m + n)];
Q('m01', mk.mcq({ stem: r`For $A(x_1, y_1)$ and $B(x_2, y_2)$, which expression gives the $x$-coordinate of the point $P$ of $AB$ with $AP : PB = m_1 : m_2$?`, opts: [r`$\dfrac{m_1x_2 + m_2x_1}{m_1 + m_2}$`, r`$\dfrac{m_1x_1 + m_2x_2}{m_1 + m_2}$`, r`$\dfrac{m_1x_2 + m_2x_1}{m_1m_2}$`, r`$\dfrac{x_1 + x_2}{m_1 + m_2}$`], key: 'a', sol: r`Pair $m_1$ with the far end $B$ and $m_2$ with $A$, then divide by $m_1 + m_2$. Option (b) pairs each part of the ratio with the wrong end: it gives the point with $AP : PB = m_2 : m_1$. Options (c) and (d) do not even give the mid-point when $m_1 = m_2$.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => {
  const ok = (f) => t01.every(([x1, x2, m, n]) => Math.abs(f(x1, x2, m, n) - section(p(x1, 0), p(x2, 7), m, n)[0].num()) < 1e-12);
  C.assert(t01.every(([x1, x2, m, n]) => Math.abs(f01[1](x1, x2, m, n) - section(p(x1, 0), p(x2, 7), n, m)[0].num()) < 1e-12), '(b) is the m2 : m1 point');
  C.which(f01.map((f) => (ok(f) ? 'formula' : 'no')), 'formula');
});

const a02 = p(-9, 4), b02 = p(5, -12), o02 = [p(-2, -4), p(7, -8), p(-4, -8), p(14, -16)], w02 = A([midLine(a02, b02, 0), midLine(a02, b02, 1)]);
Q('m02', mk.mcq({ stem: r`Which point is exactly halfway between $(-9, 4)$ and $(5, -12)$?`, opts: co(o02), key: 'a', sol: r`Add the coordinates and halve: ${w02.md[0]} and ${w02.md[1]}, so the point is $(-2, -4)$. Option (c) forgets to halve the sums, and (b) halves the differences instead of the sums.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { w02.verify(C); C.assert(is(o02[1], [(5 + 9) / 2, (-12 - 4) / 2]) && is(o02[2], [-9 + 5, 4 - 12]) && is(o02[3], [5 + 9, -12 - 4]), 'distractors'); whichPt(C, o02, mid(a02, b02)); });

const v03 = [p(4, -2), p(-1, 7), p(6, 1)], o03 = [p(3, 2), p(9, 6), p([9, 2], 3), p([3, 2], [5, 2])], w03 = A([centLine(...v03, 0), centLine(...v03, 1)]);
Q('m03', mk.mcq({ stem: r`A triangle has its corners at $(4, -2)$, $(-1, 7)$ and $(6, 1)$. Where do its medians meet?`, opts: co(o03), key: 'a', sol: r`The medians meet at the centroid: ${w03.md[0]} and ${w03.md[1]}, so it is $(3, 2)$. Option (b) adds the coordinates without dividing by $3$, (c) divides by $2$, and (d) is only the mid-point of the first two corners.`, d: 1, c: 'understanding', t: [3], time: 60 }), (C) => { w03.verify(C); C.assert(is(o03[1], [9, 6]) && same(o03[2], p(F(9, 2), F(6, 2))) && same(o03[3], mid(v03[0], v03[1])), 'distractors'); whichPt(C, o03, centroid(...v03)); });

const a04 = p(2, -6), b04 = p(-8, 4), o04 = [p(-4, 0), p(-2, -2), p(-3, -1), p(-20, 0)], w04 = A([secLine(a04, b04, 3, 2, 0), secLine(a04, b04, 3, 2, 1)]);
Q('m04', mk.mcq({ stem: r`$A(2, -6)$ and $B(-8, 4)$ are joined. Where is the point $P$ on $AB$ with $AP : PB = 3 : 2$?`, opts: co(o04), key: 'a', sol: r`$x = ${w04.lines[0]}$ and $y = ${w04.lines[1]}$, so $P$ is $(-4, 0)$. Option (b) uses the ratio $2 : 3$, (c) is the mid-point, and (d) forgets to divide by $3 + 2$.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { w04.verify(C); C.assert(same(o04[1], section(a04, b04, 2, 3)) && same(o04[2], mid(a04, b04)) && is(o04[3], [3 * -8 + 2 * 2, 3 * 4 + 2 * -6]), 'distractors'); whichPt(C, o04, section(a04, b04, 3, 2)); });

const a05 = p(0, 0), b05 = p(10, 5), v05 = [F(1, 5), F(1, 4), F(4, 5), F(1, 3)];
Q('m05', mk.mcq({ stem: r`A point $P$ of the segment $AB$ satisfies $AP : PB = 1 : 4$. What fraction of the whole length $AB$ is $AP$?`, opts: v05.map((v) => r`$\dfrac{${v.n}}{${v.d}}$`), key: 'a', sol: r`$AP$ is $1$ part and $PB$ is $4$ parts, so $AB$ is $1 + 4 = 5$ parts and $AP = \dfrac{1}{5}AB$. Option (b) compares $AP$ with $PB$ instead of with $AB$, and (c) is the fraction for $PB$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { A([r`1 + 4 = 5`]).verify(C); const P5 = section(a05, b05, 1, 4); const k2 = dist2(a05, P5).div(dist2(a05, b05)); C.assert(dist2(P5, b05).div(dist2(a05, b05)).eq(v05[2].pow(2)), '(c) is PB : AB'); C.which(v05.map((v) => v.pow(2).toString()), k2.toString()); });

const a06 = p(-2, -3), b06 = p(5, 6), o06 = [[1, 2], [2, 1], [2, 5], [5, 2]], w06 = K(F(1, 2), [r`\dfrac{6k + (-3)}{k + 1} = 0 \Rightarrow 6k = 3 \Rightarrow k = \dfrac{1}{2}`]);
Q('m06', mk.mcq({ stem: r`The segment with ends $A(-2, -3)$ and $B(5, 6)$ crosses the $x$-axis at $P$. The ratio $AP : PB$ is`, opts: ro(o06), key: 'a', sol: r`Every point of the $x$-axis has $y = 0$. Let $AP : PB = k : 1$: ${w06.md[0]}, so the ratio is $1 : 2$. Option (b) is $PB : AP$, and (c) wrongly sets the $x$-coordinate to zero, which is the $y$-axis condition.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { w06.verify(C); C.assert(rt(axisCut(a06, b06, 'y').r) === rt(o06[2]), '(c) is the y-axis ratio'); whichR(C, o06, axisCut(a06, b06, 'x').r); });

const a07 = p(-4, -3), b07 = p(5, 3), p07 = p(2, 1), o07 = [[2, 1], [1, 2], [3, 2], [2, 3]], w07 = K(2, [r`\dfrac{5k + (-4)}{k + 1} = 2 \Rightarrow 5k - 4 = 2k + 2 \Rightarrow k = 2`]), w07b = A([secLine(a07, b07, 2, 1, 1)]);
Q('m07', mk.mcq({ stem: r`The point $P(2, 1)$ lies on the line segment from $A(-4, -3)$ to $B(5, 3)$. Find $AP : PB$.`, opts: ro(o07), key: 'a', sol: r`Take $AP : PB = k : 1$ and use the $x$-coordinates: ${w07.md[0]}. The $y$-coordinate agrees: ${w07b.md[0]}. Option (b) is $PB : AP$, (c) is $AB : AP$ and (d) is $AP : AB$.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { w07.verify(C); w07b.verify(C); const k = ratioOf(a07, b07, p07); const ab = p07[0].sub(a07[0]).div(b07[0].sub(a07[0])); C.assert(rt([ab.n, ab.d]) === rt(o07[3]) && rt([ab.d, ab.n]) === rt(o07[2]), '(c), (d) are AB : AP and AP : AB'); whichR(C, o07, k); });

const p08 = p(7, 4), m08 = p(3, -1), o08 = [p(-1, -6), p(5, [3, 2]), p(-4, -5), p(10, 3)], w08 = A([endLine(p08, m08, 0), endLine(p08, m08, 1)]);
Q('m08', mk.mcq({ stem: r`$M(3, -1)$ is the mid-point of $PQ$, and $P$ is $(7, 4)$. The coordinates of $Q$ are`, opts: co(o08), key: 'a', sol: r`$Q$ is as far beyond $M$ as $P$ is before it: ${w08.md[0]} and ${w08.md[1]}, so $Q$ is $(-1, -6)$. Option (b) is the mid-point of $PM$, (c) subtracts $P$ from $M$, and (d) adds them.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w08.verify(C); C.assert(same(o08[1], mid(p08, m08)) && is(o08[2], [3 - 7, -1 - 4]) && is(o08[3], [10, 3]), 'distractors'); whichPt(C, o08, otherEnd(p08, m08)); });

const a09 = p(-1, 4), b09 = p(5, 2), g09 = p(1, 3), o09 = [p(-1, 3), p(-3, -3), p([5, 3], 3), p(-2, 0)], w09 = A([thirdLine(a09, b09, g09, 0), thirdLine(a09, b09, g09, 1)]);
Q('m09', mk.mcq({ stem: r`A triangle has two vertices at $(-1, 4)$ and $(5, 2)$, and its medians meet at $(1, 3)$. Where is the third vertex?`, opts: co(o09), key: 'a', sol: r`The medians meet at the centroid, so the three $x$-coordinates add up to $3 \times 1$ and the three $y$-coordinates to $3 \times 3$: ${w09.md[0]} and ${w09.md[1]}. Option (b) forgets to multiply by $3$, (c) averages the two vertices with the centroid, and (d) multiplies by $2$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { w09.verify(C); C.assert(is(o09[1], [1 + 1 - 5, 3 - 4 - 2]) && same(o09[2], centroid(a09, b09, g09)) && is(o09[3], [2 + 1 - 5, 6 - 4 - 2]), 'distractors'); whichPt(C, o09, thirdVertex(a09, b09, g09)); });

const v10 = [p(-3, 2), p(1, -1), p(4, 3)], o10 = [p(0, 6), p(-6, -2), p(8, 0), p([1, 2], [5, 2])], w10 = A([fourthLine(...v10, 0), fourthLine(...v10, 1)]);
Q('m10', mk.mcq({ stem: r`$PQRS$ is a parallelogram (vertices in order) with $P(-3, 2)$, $Q(1, -1)$ and $R(4, 3)$. Which point is $S$?`, opts: co(o10), key: 'a', sol: r`The diagonals $PR$ and $QS$ have the same mid-point, so the coordinates of $S$ are those of $P$ plus those of $R$ minus those of $Q$: ${w10.md[0]} and ${w10.md[1]}. Option (b) uses $P + Q - R$, (c) uses $Q + R - P$, and (d) is only the mid-point of $PR$.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { w10.verify(C); C.assert(same(o10[1], fourthVertex(v10[0], v10[2], v10[1])) && same(o10[2], fourthVertex(v10[1], v10[0], v10[2])) && same(o10[3], mid(v10[0], v10[2])), 'distractors P + Q - R, Q + R - P, mid-point of PR'); whichPt(C, o10, fourthVertex(...v10)); });

const a11 = p(1, 5), b11 = p(9, -3), w11 = A([secLine(a11, b11, 1, 3, 0), secLine(a11, b11, 1, 3, 1)]);
const o11 = [r`nearer to $A$ than to $B$`, r`nearer to $B$ than to $A$`, r`exactly halfway between $A$ and $B$`, r`outside the segment $AB$`];
Q('m11', mk.mcq({ stem: r`Where does the point $P$ with $AP : PB = 1 : 3$ lie, for the segment from $A(1, 5)$ to $B(9, -3)$?`, opts: o11, key: 'a', sol: r`$AP$ is $1$ part and $PB$ is $3$ parts, so $P$ is nearer to $A$. Indeed $x = ${w11.lines[0]}$ and $y = ${w11.lines[1]}$: $P(3, 3)$ is a quarter of the way from $A$ to $B$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { w11.verify(C); const P11 = section(a11, b11, 1, 3); C.assert(is(P11, [3, 3]), 'P(3, 3)'); const d = dist2(a11, P11), e = dist2(P11, b11); C.which(['A', 'B', 'mid', 'out'], !between(a11, b11, P11) ? 'out' : d.eq(e) ? 'mid' : d.lt(e) ? 'A' : 'B'); });

const t12 = [p(-4, 7), p(5, 4), p(-1, -2)], o12 = [[2, 1], [1, 2], [1, 1], [3, 1]];
Q('m12', mk.mcq({ stem: r`In triangle $ABC$, $D$ is the mid-point of $BC$ and $G$ is the point where the medians meet. The ratio $AG : GD$ is`, opts: ro(o12), key: 'a', sol: r`The centroid lies two-thirds of the way along each median from the vertex, so $AG$ is twice $GD$. Option (b) measures from the side instead of from the vertex.`, d: 2, c: 'understanding', t: [3], time: 45 }), (C) => { const G = centroid(...t12), D = mid(t12[1], t12[2]); whichR(C, o12, ratioOf(t12[0], D, G)); });

const a13 = p(3, -1), b13 = p(8, 9), o13 = [[2, 3], [3, 2], [1, 1], [1, 2]], w13 = K(F(2, 3), [r`(8k + 3) - (9k - 1) = 2(k + 1) \Rightarrow -k + 4 = 2k + 2 \Rightarrow 3k = 2 \Rightarrow k = \dfrac{2}{3}`]), w13b = A([r`5 - 3 = 2`]);
Q('m13', mk.mcq({ stem: r`The straight line $x - y = 2$ meets the segment joining $A(3, -1)$ and $B(8, 9)$. In what ratio does it divide $AB$?`, opts: ro(o13), key: 'a', sol: r`Let the ratio be $k : 1$; the meeting point is $\left(\dfrac{8k + 3}{k + 1}, \dfrac{9k - 1}{k + 1}\right)$. It lies on the line: ${w13.md[0]}. So the ratio is $2 : 3$, and the point is $(5, 3)$; check: ${w13b.md[0]}. Option (b) is the ratio the other way round, and (c) assumes the line passes through the mid-point $\left(\dfrac{11}{2}, 4\right)$, which it does not.`, d: 3, c: 'application', t: [1], time: 120 }), (C) => { w13.verify(C); w13b.verify(C); const cut = lineCut(a13, b13, [1, -1, 2]); C.assert(is(cut.P, [5, 3]) && is(mid(a13, b13), [[11, 2], 4]) && !mid(a13, b13)[0].sub(mid(a13, b13)[1]).eq(2), 'point (5, 3); mid-point not on the line'); whichR(C, o13, cut.r); });

const a14 = p(-6, 10), b14 = p(9, -5), o14 = [p(4, 0), p(-1, 5), p([3, 2], [5, 2]), p(6, 0)], w14 = A([secLine(a14, b14, 2, 1, 0), secLine(a14, b14, 2, 1, 1)]);
Q('m14', mk.mcq({ stem: r`$A(-6, 10)$ and $B(9, -5)$ are joined, and the segment is cut into three equal parts. Which of the two cutting points lies closer to $B$?`, opts: co(o14), key: 'a', sol: r`The point closer to $B$ has $AP : PB = 2 : 1$: $x = ${w14.lines[0]}$ and $y = ${w14.lines[1]}$, giving $(4, 0)$. Option (b) is the cutting point closer to $A$, (c) is the mid-point, and (d) divides by $2$ instead of by $2 + 1$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { w14.verify(C); C.assert(same(o14[1], section(a14, b14, 1, 2)) && same(o14[2], mid(a14, b14)) && is(o14[3], [(2 * 9 - 6) / 2, (2 * -5 + 10) / 2]), 'distractors'); whichPt(C, o14, section(a14, b14, 2, 1)); });

const w15 = W(eqctx('p', [-7]), [r`\dfrac{p + 5}{2} = -1 \Rightarrow p + 5 = -2 \Rightarrow p = -7`]), w15b = A([r`q = \dfrac{7 + (-3)}{2} = 2`, r`p + q = -7 + 2 = -5`]);
Q('m15', mk.mcq({ stem: r`The mid-point of the segment from $(p, 7)$ to $(5, -3)$ is $(-1, q)$. What is $p + q$?`, opts: ['$-5$', '$5$', '$-4$', '$-3$'], key: 'a', sol: r`From the $x$-coordinates, ${w15.md[0]}; from the $y$-coordinates, ${w15b.md[0]}. So ${w15b.md[1]}. Option (b) comes from the sign slip $p = 2 \times (-1) + 5$, (c) from $p = -1 - 5$, and (d) from forgetting to halve $7 + (-3)$.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { w15.verify(C); w15b.verify(C); const M = mid(p(-7, 7), p(5, -3)); C.assert(is(M, [-1, 2]), 'mid-point (−1, 2)'); C.which([-5, 2 * -1 + 5 + 2, -1 - 5 + 2, -7 + (7 - 3)], -7 + 2); });

const v16 = [p(0, 0), p(9, 0), p(0, -6)], o16 = [p(3, -2), p([9, 2], -3), p(9, -6), p(-3, 2)], w16 = A([centLine(...v16, 0), centLine(...v16, 1)]);
Q('m16', mk.mcq({ stem: r`What is the centroid of the right-angled triangle with vertices $O(0, 0)$, $A(9, 0)$ and $B(0, -6)$?`, opts: co(o16), key: 'a', sol: r`${w16.md[0]} and ${w16.md[1]}, so the centroid is $(3, -2)$. Option (b) is the mid-point of the hypotenuse $AB$, (c) forgets to divide by $3$, and (d) has both signs reversed.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { w16.verify(C); C.assert(same(o16[1], mid(v16[1], v16[2])) && is(o16[2], [9, -6]), 'distractors'); whichPt(C, o16, centroid(...v16)); });

const a17 = p(-2, 3), b17 = p(4, -1), P17 = section(a17, b17, 1, 2), Q17 = section(a17, b17, 2, 1), o17 = [p(1, 1), p(0, [5, 3]), p(2, [1, 3]), p(2, 2)], w17 = A([midLine(a17, b17, 0), midLine(a17, b17, 1)]);
Q('m17', mk.mcq({ stem: r`$P$ and $Q$ are the two points that cut the segment from $A(-2, 3)$ to $B(4, -1)$ into three equal parts. Which point is the mid-point of $PQ$?`, opts: co(o17), key: 'a', sol: r`$AP = QB$, so $PQ$ and $AB$ share their mid-point: ${w17.md[0]} and ${w17.md[1]}, giving $(1, 1)$. Check: $P$ is $${ct(P17)}$ and $Q$ is $${ct(Q17)}$, and the point halfway between them is again $(1, 1)$. Options (b) and (c) are $P$ and $Q$ themselves; (d) adds the coordinates of $A$ and $B$ without halving.`, d: 3, c: 'analysis', t: [1, 2], time: 90 }), (C) => { w17.verify(C); C.assert(same(o17[1], P17) && same(o17[2], Q17) && is(o17[3], [2, 2]), 'distractors'); C.assert(same(mid(P17, Q17), mid(a17, b17)), 'same mid-point'); whichPt(C, o17, mid(P17, Q17)); });

const a18 = p(-4, 7), d18 = p(2, 1), o18 = [p(0, 3), p(-2, 5), p(-1, 4), p([-2, 3], [8, 3])], w18 = A([secLine(a18, d18, 2, 1, 0), secLine(a18, d18, 2, 1, 1)]);
Q('m18', mk.mcq({ stem: r`In triangle $ABC$, the vertex $A$ is $(-4, 7)$ and the mid-point of $BC$ is $D(2, 1)$. Find the centroid of the triangle.`, opts: co(o18), key: 'a', sol: r`The centroid divides the median $AD$ in the ratio $2 : 1$ from $A$: $x = ${w18.lines[0]}$ and $y = ${w18.lines[1]}$, so it is $(0, 3)$. Option (b) uses the ratio $1 : 2$, (c) is the mid-point of $AD$, and (d) divides the sum of $A$ and $D$ by $3$.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { w18.verify(C); C.assert(same(o18[1], section(a18, d18, 1, 2)) && same(o18[2], mid(a18, d18)) && is(o18[3], [[-2, 3], [8, 3]]), 'distractors'); const B = p(5, 4), Cc = p(-1, -2); C.assert(same(mid(B, Cc), d18), 'a triangle with this median exists'); whichPt(C, o18, centroid(a18, B, Cc)); });

// =============================================================== assertion-reason (keys a c d b a c)
const w1 = A([midLine(p(-5, 8), p(3, -2), 0), midLine(p(-5, 8), p(3, -2), 1)]);
Q('ar1', mk.ar({ a: r`The mid-point of the segment joining $(-5, 8)$ and $(3, -2)$ is $(-1, 3)$.`, r: r`The mid-point of a segment divides it internally in the ratio $1 : 1$, so each of its coordinates is the average of the end coordinates.`, key: 'a', sol: r`A is true: ${w1.md[0]} and ${w1.md[1]}. R is true, and averaging the end coordinates is exactly how A is obtained, so R explains A.`, d: 1, c: 'understanding', t: [2] }), (C) => { w1.verify(C); C.assert(is(mid(p(-5, 8), p(3, -2)), [-1, 3]), 'A true'); C.key('a'); });

const w2 = K(F(1, 2), [r`\dfrac{6k + (-3)}{k + 1} = 0 \Rightarrow 6k = 3 \Rightarrow k = \dfrac{1}{2}`]);
Q('ar2', mk.ar({ a: r`The segment from $(-3, 2)$ to $(6, 5)$ is cut by the $y$-axis into two pieces in the ratio $1 : 2$.`, r: r`Points lying on the $y$-axis all have their $y$-coordinate equal to $0$.`, key: 'c', sol: r`A is true: on the $y$-axis $x = 0$, so with the ratio $k : 1$, ${w2.md[0]}, which is $1 : 2$. R is false: the points of the $y$-axis have $x$-coordinate $0$; it is the $x$-axis whose points have $y$-coordinate $0$.`, d: 2, c: 'understanding', t: [1] }), (C) => { w2.verify(C); C.assert(rt(axisCut(p(-3, 2), p(6, 5), 'y').r) === '1 : 2', 'A true'); C.key('c'); });

const a3 = p(0, 6), b3 = p(9, -3), w3 = A([secLine(a3, b3, 1, 2, 0), secLine(a3, b3, 1, 2, 1)]);
Q('ar3', mk.ar({ a: r`The point dividing the join of $A(0, 6)$ and $B(9, -3)$ in the ratio $1 : 2$ is $(6, 0)$.`, r: r`When $m_1 < m_2$, the point dividing $AB$ in the ratio $m_1 : m_2$ is nearer to $A$ than to $B$.`, key: 'd', sol: r`A is false: $x = ${w3.lines[0]}$ and $y = ${w3.lines[1]}$, so the point is $(3, 3)$; the point $(6, 0)$ divides $AB$ in the ratio $2 : 1$. R is true: $AP$ is the smaller share of $AB$.`, d: 2, c: 'understanding', t: [1] }), (C) => { w3.verify(C); const P3 = section(a3, b3, 1, 2); C.assert(is(P3, [3, 3]) && is(section(a3, b3, 2, 1), [6, 0]) && dist2(a3, P3).lt(dist2(P3, b3)), 'A false, R true here'); C.key('d'); });

const v4 = [p(1, 2), p(7, 2), p(4, 8)], w4 = A([centLine(...v4, 0), centLine(...v4, 1)]);
Q('ar4', mk.ar({ a: r`The centroid of the triangle with vertices $(1, 2)$, $(7, 2)$ and $(4, 8)$ is $(4, 4)$.`, r: r`The triangle with these three vertices is isosceles.`, key: 'b', sol: r`A is true: ${w4.md[0]} and ${w4.md[1]}. R is also true, as the two sides from $(4, 8)$ both have length $\sqrt{45}$. But the centroid comes from averaging the vertices, which works for every triangle, so R does not explain A.`, d: 2, c: 'analysis', t: [3] }), (C) => { w4.verify(C); C.assert(is(centroid(...v4), [4, 4]) && dist2(v4[2], v4[0]).eq(45) && dist2(v4[2], v4[1]).eq(45), 'A true, R true'); C.key('b'); });

const a5 = p(1, 3), m5 = p(4, -1), w5 = A([endLine(a5, m5, 0), endLine(a5, m5, 1)]);
Q('ar5', mk.ar({ a: r`If $(4, -1)$ is the mid-point of $AB$ and $A$ is $(1, 3)$, then $B$ is $(7, -5)$.`, r: r`If $M(x, y)$ is the mid-point of $AB$ and $A$ is $(x_1, y_1)$, then $B$ is $(2x - x_1, 2y - y_1)$.`, key: 'a', sol: r`A is true: ${w5.md[0]} and ${w5.md[1]}, which is R applied to these points. Both statements are true and R explains A.`, d: 2, c: 'understanding', t: [2] }), (C) => { w5.verify(C); C.assert(is(otherEnd(a5, m5), [7, -5]), 'A true'); C.key('a'); });

const v6 = [p(-1, 3), p(4, -5), p(3, -1)], w6 = A([centLine(...v6, 0), centLine(...v6, 1)]);
Q('ar6', mk.ar({ a: r`$G(2, -1)$ is the centroid of the triangle with vertices $(-1, 3)$, $(4, -5)$ and $(3, -1)$.`, r: r`The centroid divides each median in the ratio $1 : 2$, measured from the vertex.`, key: 'c', sol: r`A is true: ${w6.md[0]} and ${w6.md[1]}. R is false: measured from the vertex the ratio is $2 : 1$, so the centroid is nearer to the side than to the vertex.`, d: 2, c: 'understanding', t: [3] }), (C) => { w6.verify(C); const G = centroid(...v6); C.assert(is(G, [2, -1]) && rt(ratioOf(v6[0], mid(v6[1], v6[2]), G)) === '2 : 1', 'A true, R false'); C.key('c'); });

// =============================================================== true-false
const at1 = p(-4, 6), bt1 = p(8, -2), wt1 = A([secLine(at1, bt1, 2, 2, 0), secLine(at1, bt1, 2, 2, 1)]);
Q('tf1', mk.tf({ stem: r`Dividing the join of $(-4, 6)$ and $(8, -2)$ internally in the ratio $2 : 2$ gives its mid-point, $(2, 2)$.`, key: 't', sol: r`True. The ratio $2 : 2$ is the same as $1 : 1$: $x = ${wt1.lines[0]}$ and $y = ${wt1.lines[1]}$, which is the mid-point.`, d: 1, c: 'understanding', t: [1, 2] }), (C) => { wt1.verify(C); C.assert(same(section(at1, bt1, 2, 2), mid(at1, bt1)) && is(mid(at1, bt1), [2, 2]), 'mid-point (2, 2)'); C.key('t'); });

const at2 = p(1, -4), bt2 = p(11, 6), wt2 = A([secLine(at2, bt2, 2, 3, 0), secLine(at2, bt2, 2, 3, 1)]);
Q('tf2', mk.tf({ stem: r`The point $P$ on the segment from $A(1, -4)$ to $B(11, 6)$ with $AP : PB = 2 : 3$ is $(7, 2)$.`, key: 'f', sol: r`False. $x = ${wt2.lines[0]}$ and $y = ${wt2.lines[1]}$, so $P$ is $(5, 0)$. The point $(7, 2)$ has $AP : PB = 3 : 2$: the parts of the ratio were paired with the wrong ends.`, d: 2, c: 'understanding', t: [1] }), (C) => { wt2.verify(C); C.assert(is(section(at2, bt2, 2, 3), [5, 0]) && is(section(at2, bt2, 3, 2), [7, 2]), 'P(5, 0); (7, 2) is 3 : 2'); C.key('f'); });

const wt3 = K(F(1, 3), [r`\dfrac{6k + (-2)}{k + 1} = 0 \Rightarrow 6k = 2 \Rightarrow k = \dfrac{1}{3}`]);
Q('tf3', mk.tf({ stem: r`The $x$-axis cuts the join of $P(5, -2)$ and $Q(-7, 6)$ in the ratio $1 : 3$.`, key: 't', sol: r`True. On the $x$-axis $y = 0$; with the ratio $k : 1$, ${wt3.md[0]}, so the ratio is $1 : 3$ and the axis is met at $(2, 0)$.`, d: 2, c: 'application', t: [1] }), (C) => { wt3.verify(C); const cut = axisCut(p(5, -2), p(-7, 6), 'x'); C.assert(rt(cut.r) === '1 : 3' && is(cut.P, [2, 0]), '1 : 3 at (2, 0)'); C.key('t'); });

const vt4 = [p(0, 0), p(6, 0), p(0, 9)], wt4 = A([centLine(...vt4, 0), centLine(...vt4, 1)]);
Q('tf4', mk.tf({ stem: r`The centroid of a triangle can lie on one of the triangle's sides.`, key: 'f', sol: r`False. The centroid is two-thirds of the way along every median from the vertex, so it is always strictly inside the triangle. For the vertices $(0, 0)$, $(6, 0)$ and $(0, 9)$, for example, ${wt4.md[0]} and ${wt4.md[1]}: the centroid $(2, 3)$ is inside, on none of the sides.`, d: 1, c: 'understanding', t: [3] }), (C) => { wt4.verify(C); const G = centroid(...vt4); C.assert(is(G, [2, 3]) && inside(vt4, G) && !collinear(vt4[0], vt4[1], G) && !collinear(vt4[1], vt4[2], G) && !collinear(vt4[2], vt4[0], G), 'strictly inside'); C.key('f'); });

const vt5 = [p(1, 1), p(7, 3), p(1, 5)], mt5 = [mid(vt5[1], vt5[2]), mid(vt5[2], vt5[0]), mid(vt5[0], vt5[1])], wt5 = A([centLine(...vt5, 0), centLine(...vt5, 1), centLine(...mt5, 0), centLine(...mt5, 1)]);
Q('tf5', mk.tf({ stem: r`A triangle and the triangle formed by joining the mid-points of its sides always have the same centroid.`, key: 't', sol: r`True. Each vertex coordinate is used in two of the mid-points, each time halved, so the mid-points' coordinates add up to the same totals as the vertices'. For the vertices $(1, 1)$, $(7, 3)$, $(1, 5)$ the mid-points are ${mt5.map((q) => `$${ct(q)}$`).join(', ')}; ${wt5.md[0]} and ${wt5.md[2]}, while ${wt5.md[1]} and ${wt5.md[3]}.`, d: 2, c: 'analysis', t: [2, 3] }), (C) => { wt5.verify(C); C.assert(same(centroid(...vt5), centroid(...mt5)) && fromMidpoints(...mt5).every((q, i) => same(q, vt5[i])), 'same centroid; vertices recovered'); C.key('t'); });

const at6 = p(-1, 3), mt6 = p(2, 5), wt6 = A([endLine(at6, mt6, 0), endLine(at6, mt6, 1)]);
Q('tf6', mk.tf({ stem: r`If $M(2, 5)$ is the mid-point of $AB$ and $A$ is $(-1, 3)$, then $B$ is $\left(\dfrac{1}{2}, 4\right)$.`, key: 'f', sol: r`False. $\left(\dfrac{1}{2}, 4\right)$ is the mid-point of $AM$. $B$ is as far beyond $M$ as $A$ is before it: ${wt6.md[0]} and ${wt6.md[1]}, so $B$ is $(5, 7)$.`, d: 2, c: 'application', t: [2] }), (C) => { wt6.verify(C); C.assert(is(otherEnd(at6, mt6), [5, 7]) && is(mid(at6, mt6), [[1, 2], 4]), 'B(5, 7); the trap is mid AM'); C.key('f'); });

// =============================================================== fill in the blank
const wf1 = A([midLine(p(-6, 11), p(10, -3), 0)]);
Q('fb1', mk.fill({ stem: r`The point halfway between $(-6, 11)$ and $(10, -3)$ has $x$-coordinate ___.`, acc: [['2']], sol: r`${wf1.md[0]}; the point is $(2, 4)$.`, d: 1, c: 'understanding', t: [2] }), (C) => { wf1.verify(C); C.blank(mid(p(-6, 11), p(10, -3))[0].num()); });

const af2 = p(-8, 3), bf2 = p(4, -9), wf2 = K(2, [r`\dfrac{4k + (-8)}{k + 1} = 0 \Rightarrow 4k = 8 \Rightarrow k = 2`]), wf2b = A([secLine(af2, bf2, 2, 1, 1)]);
Q('fb2', mk.fill({ stem: r`The $y$-axis cuts the segment from $(-8, 3)$ to $(4, -9)$ at the point $(0, c)$, where $c$ = ___.`, acc: [['-5', '−5']], sol: r`On the $y$-axis $x = 0$; with the ratio $k : 1$, ${wf2.md[0]}. So $c = ${wf2b.lines[0]}$.`, d: 2, c: 'application', t: [1] }), (C) => { wf2.verify(C); wf2b.verify(C); C.blank(axisCut(af2, bf2, 'y').P[1].num()); });

const vf3 = [p(5, -3), p(-2, 4), p(6, 8)], wf3 = A([centLine(...vf3, 1)]);
Q('fb3', mk.fill({ stem: r`The centroid of the triangle with vertices $(5, -3)$, $(-2, 4)$ and $(6, 8)$ has $y$-coordinate ___.`, acc: [['3']], sol: r`${wf3.md[0]}.`, d: 1, c: 'understanding', t: [3] }), (C) => { wf3.verify(C); C.blank(centroid(...vf3)[1].num()); });

Q('fb4', mk.fill({ stem: r`A point that divides a line segment internally in the ratio $1 : 1$ is called the ___ of the segment.`, acc: [['mid-point', 'midpoint', 'mid point']], sol: r`The two parts are equal, so the point is the mid-point.`, d: 1, c: 'recall', t: [2] }), (C) => { const a = p(2, 7), b = p(-6, 1); C.blank(same(section(a, b, 1, 1), mid(a, b)) ? 'mid-point' : 'none'); });

const vf5 = [p(-4, 1), p(8, 3), p(2, -7)];
Q('fb5', mk.fill({ stem: r`Measured from the vertex, the centroid divides every median of a triangle in the ratio ___ : 1.`, acc: [['2']], sol: r`The centroid is two-thirds of the way along each median from the vertex, so the ratio is $2 : 1$.`, d: 1, c: 'recall', t: [3] }), (C) => { const G = centroid(...vf5); const r0 = ratioOf(vf5[0], mid(vf5[1], vf5[2]), G); C.assert(r0[1] === 1, 'ratio k : 1'); C.blank(r0[0]); });

const af6 = p(3, -5), mf6 = p(-1, 2), wf6 = A([endLine(af6, mf6, 0)]);
Q('fb6', mk.fill({ stem: r`$A$ is $(3, -5)$ and the mid-point of $AB$ is $(-1, 2)$. The $x$-coordinate of $B$ is ___.`, acc: [['-5', '−5']], sol: r`${wf6.md[0]}; the point is $B${ct(otherEnd(af6, mf6))}$.`, d: 2, c: 'understanding', t: [2] }), (C) => { wf6.verify(C); C.blank(otherEnd(af6, mf6)[0].num()); });

// =============================================================== numerical
const an1 = p(-3, 8), bn1 = p(9, -4), wn1 = A([secLine(an1, bn1, 3, 1, 0)]);
Q('n01', mk.num({ stem: r`$P$ divides the join of $(-3, 8)$ and $(9, -4)$ internally in the ratio $3 : 1$. Find the $x$-coordinate of $P$.`, value: 6, sol: r`$x = ${wn1.lines[0]}$.`, scheme: [['x = 6', 1]], d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { wn1.verify(C); C.val(section(an1, bn1, 3, 1)[0].num()); });

const tn2 = [p(-4, 7), p(5, 3), p(-1, -5)], dn2 = mid(tn2[1], tn2[2]), wn2 = A([midLine(tn2[1], tn2[2], 0), midLine(tn2[1], tn2[2], 1), r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`]);
Q('n02', mk.num({ marks: 2, stem: r`Triangle $ABC$ has $A(-4, 7)$, $B(5, 3)$ and $C(-1, -5)$. Find the length of the median from $A$.`, value: 10, sol: r`The median joins $A$ to the mid-point $D$ of $BC$: ${wn2.md[0]} and ${wn2.md[1]}, so $D$ is $${ct(dn2)}$. Then $AD = ${wn2.lines[2]}$ units.`, scheme: [['D(2, −1)', 1], ['AD = 10 units', 1]], d: 3, c: 'application', t: [2, 3], time: 120 }), (C) => { wn2.verify(C); C.val(dist(tn2[0], dn2).num()); });

const an3 = p(1, -4), bn3 = p(7, 5), wn3 = K(2, [r`\dfrac{5k + (-4)}{k + 1} = 2 \Rightarrow 5k - 4 = 2k + 2 \Rightarrow k = 2`]), wn3b = A([secLine(an3, bn3, 2, 1, 0)]);
Q('n03', mk.num({ stem: r`The point $P(a, 2)$ lies on the segment joining $A(1, -4)$ and $B(7, 5)$. Find $a$.`, value: 5, sol: r`Let $AP : PB = k : 1$. From the $y$-coordinates, ${wn3.md[0]}. Then $a = ${wn3b.lines[0]}$.`, scheme: [['a = 5', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { wn3.verify(C); wn3b.verify(C); C.val(cutAt(an3, bn3, 1, 2).P[0].num()); });

const an4 = p(-1, 5), bn4 = p(6, -8), gn4 = p(3, -2), cn4 = thirdVertex(an4, bn4, gn4), wn4 = A([thirdLine(an4, bn4, gn4, 0), thirdLine(an4, bn4, gn4, 1), r`\sqrt{4^2 + 3^2} = \sqrt{25} = 5`]);
Q('n04', mk.num({ marks: 2, stem: r`The centroid of a triangle is $(3, -2)$ and two of its vertices are $(-1, 5)$ and $(6, -8)$. How far is the third vertex from the origin?`, value: 5, sol: r`Third vertex: ${wn4.md[0]} and ${wn4.md[1]}, so it is $${ct(cn4)}$. Its distance from the origin is ${wn4.md[2]} units.`, scheme: [['Third vertex (4, −3)', 1], ['Distance 5 units', 1]], d: 3, c: 'application', t: [3], time: 120 }), (C) => { wn4.verify(C); C.val(dist(cn4, p(0, 0)).num()); });

const wn5 = K(10, [r`\dfrac{2k + 5 \times (-4)}{2 + 5} = 0 \Rightarrow 2k = 20 \Rightarrow k = 10`]);
Q('n05', mk.num({ marks: 2, stem: r`A point of the $x$-axis splits the line segment from $(2, -4)$ to $(-5, k)$ so that its two pieces are in the ratio $2 : 5$. What is the value of $k$?`, value: 10, sol: r`The point of division lies on the $x$-axis, so its $y$-coordinate is $0$: ${wn5.md[0]}.`, scheme: [['y-coordinate of the point set to 0', 1], ['k = 10', 1]], d: 3, c: 'application', t: [1], time: 90 }), (C) => { wn5.verify(C); const ks = []; for (let k = 1; k <= 40; k++) if (rt(axisCut(p(2, -4), p(-5, k), 'x').r) === '2 : 5') ks.push(k); C.assert(ks.length === 1, 'one value by search'); C.val(ks[0]); });

const vn6 = [p(-7, 2), p(1, -8), p(3, 0)], wn6 = A([centLine(...vn6, 1)]);
Q('n06', mk.num({ stem: r`Find the $y$-coordinate of the centroid of the triangle with vertices $(-7, 2)$, $(1, -8)$ and $(3, 0)$.`, value: -2, sol: r`$y = ${wn6.lines[0]}$.`, scheme: [['y = −2', 1]], d: 1, c: 'understanding', t: [3], time: 45 }), (C) => { wn6.verify(C); C.val(centroid(...vn6)[1].num()); });

const vn7 = [p(-1, 2), p(7, 3), p(9, -4)], dn7 = fourthVertex(...vn7), wn7 = A([fourthLine(...vn7, 0), fourthLine(...vn7, 1), r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`]);
Q('n07', mk.num({ marks: 2, stem: r`$ABCD$ is a parallelogram with $A(-1, 2)$, $B(7, 3)$ and $C(9, -4)$, taken in order. Find the length of the diagonal $BD$.`, value: 10, sol: r`The diagonals bisect each other, so $D$ has the coordinates of $A$ plus those of $C$ minus those of $B$: ${wn7.md[0]} and ${wn7.md[1]}, so $D$ is $${ct(dn7)}$. Then $BD = ${wn7.lines[2]}$ units.`, scheme: [['D(1, −5)', 1], ['BD = 10 units', 1]], d: 3, c: 'application', t: [2], time: 120 }), (C) => { wn7.verify(C); C.val(dist(vn7[1], dn7).num()); });

// =============================================================== short answer, 2 marks
const a201 = p(8, -5), b201 = p(-2, 10), P201 = section(a201, b201, 2, 3), w201 = A([secLine(a201, b201, 2, 3, 0), secLine(a201, b201, 2, 3, 1)]);
Q('s201', mk.short({ marks: 2, stem: r`Calculate the coordinates of the point $P$ on the segment $AB$, where $A$ is $(8, -5)$ and $B$ is $(-2, 10)$, for which $AP : PB = 2 : 3$.`, model: J([r`Here $m_1 = 2$ and $m_2 = 3$.`, r`$x = ${w201.lines[0]}$`, r`$y = ${w201.lines[1]}$`, r`So $P$ is $${ct(P201)}$.`]), sol: r`Use the section formula, pairing $m_1$ with $B$ and $m_2$ with $A$.`, scheme: [['x = 4', 1], ['y = 1', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { w201.verify(C); C.model([ct(P201)]); C.assert(is(P201, [4, 1]), 'P(4, 1)'); });

const w202 = W(solvectx(['x', 'y'], { x: -2, y: -6 }), [r`\dfrac{(x + 1) + 7}{2} = 3 \Rightarrow x + 8 = 6 \Rightarrow x = -2`, r`\dfrac{5 + (y - 3)}{2} = -2 \Rightarrow y + 2 = -4 \Rightarrow y = -6`]);
Q('s202', mk.short({ marks: 2, stem: r`$(3, -2)$ is the mid-point of the segment whose ends are $(x + 1, 5)$ and $(7, y - 3)$. Find $x$ and $y$.`, model: J([r`Mid-point, $x$-coordinates: ${w202.md[0]}.`, r`Mid-point, $y$-coordinates: ${w202.md[1]}.`]), sol: r`Write each coordinate of the mid-point as an average and solve the two equations separately.`, scheme: [['x = −2', 1], ['y = −6', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { w202.verify(C); C.assert(is(mid(p(-2 + 1, 5), p(7, -6 - 3)), [3, -2]), 'substituted back'); C.model([2, 6]); });

const v203 = [p(-5, 1), p(3, 6), p(8, -4)], w203 = A([centLine(...v203, 0), centLine(...v203, 1)]);
Q('s203', mk.short({ marks: 2, stem: r`Find the coordinates of the centroid of triangle $PQR$ with $P(-5, 1)$, $Q(3, 6)$ and $R(8, -4)$.`, model: J([r`$x = ${w203.lines[0]}$`, r`$y = ${w203.lines[1]}$`, r`The centroid is $${ct(centroid(...v203))}$.`]), sol: r`Average the three $x$-coordinates and the three $y$-coordinates.`, scheme: [['x = 2', 1], ['y = 1', 1]], d: 1, c: 'understanding', t: [3], time: 60 }), (C) => { w203.verify(C); C.model([ct(p(2, 1))]); C.assert(is(centroid(...v203), [2, 1]), 'G(2, 1)'); });

const a204 = p(-4, -7), b204 = p(2, 5), w204 = K(2, [r`\dfrac{2k + (-4)}{k + 1} = 0 \Rightarrow 2k = 4 \Rightarrow k = 2`]), w204b = A([secLine(a204, b204, 2, 1, 1)]);
Q('s204', mk.short({ marks: 2, stem: r`The $y$-axis meets the segment from $A(-4, -7)$ to $B(2, 5)$ at the point $Q$. Find $AQ : QB$ and the coordinates of $Q$.`, model: J([r`On the $y$-axis $x = 0$. Let $AQ : QB = k : 1$: ${w204.md[0]}, so $AQ : QB = 2 : 1$.`, r`$y$-coordinate of $Q$: ${w204b.md[0]}, so $Q$ is $(0, 1)$.`]), sol: r`Set the $x$-coordinate of the division point to zero to find the ratio, then use the ratio for the $y$-coordinate.`, scheme: [['AQ : QB = 2 : 1', 1], ['Q(0, 1)', 1]], d: 2, c: 'application', t: [1], time: 120 }), (C) => { w204.verify(C); w204b.verify(C); const cut = axisCut(a204, b204, 'y'); C.assert(rt(cut.r) === '2 : 1' && is(cut.P, [0, 1]), '2 : 1 at (0, 1)'); C.model(['2 : 1', ct(cut.P)]); });

const p205 = p(-2, 2), m205 = p(1, -2), q205 = otherEnd(p205, m205), w205 = A([endLine(p205, m205, 0), endLine(p205, m205, 1), r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`]);
Q('s205', mk.short({ marks: 2, stem: r`A straight rod $PQ$ balances at its mid-point $M(1, -2)$. One end $P$ is at $(-2, 2)$. Find the other end $Q$ and the length of the rod.`, model: J([r`${w205.md[0]} and ${w205.md[1]}, so $Q$ is $${ct(q205)}$.`, r`$PQ = ${w205.lines[2]}$ units.`]), sol: r`$Q$ is as far beyond $M$ as $P$ is before it; then use the distance formula.`, scheme: [['Q(4, −6)', 1], ['PQ = 10 units', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { w205.verify(C); C.assert(is(q205, [4, -6]) && dist(p205, q205).eq(10), 'Q, length'); C.model([ct(q205), 10]); });

// =============================================================== short answer, 3 marks
const a301 = p(4, -8), b301 = p(-5, 4), P301 = section(a301, b301, 1, 2), Q301 = section(a301, b301, 2, 1);
const w301 = A([secLine(a301, b301, 1, 2, 0), secLine(a301, b301, 1, 2, 1), secLine(a301, b301, 2, 1, 0), secLine(a301, b301, 2, 1, 1), midLine(P301, b301, 0), midLine(P301, b301, 1)]);
Q('s301', mk.short({ marks: 3, stem: r`Points $P$ and $Q$ cut the segment from $A(4, -8)$ to $B(-5, 4)$ into three equal pieces, with $P$ nearer to $A$. Find $P$ and $Q$, and verify that $Q$ is the mid-point of $PB$.`, model: J([r`$P$ divides $AB$ in the ratio $1 : 2$: $x = ${w301.lines[0]}$ and $y = ${w301.lines[1]}$, so $P$ is $${ct(P301)}$.`, r`$Q$ divides $AB$ in the ratio $2 : 1$: $x = ${w301.lines[2]}$ and $y = ${w301.lines[3]}$, so $Q$ is $${ct(Q301)}$.`, r`Mid-point of $PB$: ${w301.md[4]} and ${w301.md[5]}, which is $Q$.`]), sol: r`The two points of trisection divide the segment in the ratios $1 : 2$ and $2 : 1$; then compare $Q$ with the mid-point of $PB$.`, scheme: [['P(1, −4)', 1], ['Q(−2, 0)', 1], ['mid-point of PB is Q', 1]], d: 2, c: 'application', t: [1, 2], time: 180 }), (C) => { w301.verify(C); C.assert(same(mid(P301, b301), Q301), 'Q is the mid-point of PB'); C.model([ct(P301), ct(Q301)]); C.assert(is(P301, [1, -4]) && is(Q301, [-2, 0]), 'P, Q'); });

const a302 = p(2, 9), b302 = p(8, -6), w302 = K(2, [r`\dfrac{-6k + 9}{k + 1} = -1 \Rightarrow -6k + 9 = -k - 1 \Rightarrow 5k = 10 \Rightarrow k = 2`]), w302b = A([secLine(a302, b302, 2, 1, 0)]);
Q('s302', mk.short({ marks: 3, stem: r`$R(x, -1)$ is a point of the line segment from $A(2, 9)$ to $B(8, -6)$. Find the ratio $AR : RB$ and the value of $x$.`, model: J([r`Let $AR : RB = k : 1$. Using the $y$-coordinates: ${w302.md[0]}.`, r`So $AR : RB = 2 : 1$.`, r`$x = ${w302b.lines[0]}$.`]), sol: r`Use the known $y$-coordinate to find the ratio, then the ratio to find the unknown $x$-coordinate.`, scheme: [['equation in k', 1], ['AR : RB = 2 : 1', 1], ['x = 6', 1]], d: 3, c: 'application', t: [1], time: 180 }), (C) => { w302.verify(C); w302b.verify(C); const cut = cutAt(a302, b302, 1, -1); C.assert(rt(cut.r) === '2 : 1' && is(cut.P, [6, -1]), '2 : 1, x = 6'); C.model(['2 : 1', 6]); });

const a303 = p(-3, 1), b303 = p(5, -4), g303 = p(2, 0), c303 = thirdVertex(a303, b303, g303), d303 = mid(b303, c303);
const w303 = A([thirdLine(a303, b303, g303, 0), thirdLine(a303, b303, g303, 1), midLine(b303, c303, 0), midLine(b303, c303, 1), secLine(a303, d303, 2, 1, 0), secLine(a303, d303, 2, 1, 1)]);
Q('s303', mk.short({ marks: 3, stem: r`Two vertices of triangle $ABC$ are $A(-3, 1)$ and $B(5, -4)$, and its centroid is $G(2, 0)$. Find $C$ and the mid-point $D$ of $BC$, and check that $G$ divides $AD$ in the ratio $2 : 1$.`, model: J([r`$C$: ${w303.md[0]} and ${w303.md[1]}, so $C$ is $${ct(c303)}$.`, r`$D$: ${w303.md[2]} and ${w303.md[3]}, so $D$ is $${ct(d303)}$.`, r`The point dividing $AD$ in the ratio $2 : 1$: $x = ${w303.lines[4]}$ and $y = ${w303.lines[5]}$. This is $G(2, 0)$.`]), sol: r`Three times the centroid equals the sum of the three vertices; the centroid is the $2 : 1$ point of the median from $A$.`, scheme: [['C(4, 3)', 1], ['D(9/2, −1/2)', 1], ['2 : 1 point of AD is G', 1]], d: 3, c: 'application', t: [2, 3], time: 210 }), (C) => { w303.verify(C); C.assert(is(c303, [4, 3]) && same(section(a303, d303, 2, 1), g303), 'C; G on AD'); C.model([ct(c303), ct(d303)]); });

const a304 = p(-1, -2), b304 = p(8, 7), w304 = K(F(1, 2), [r`(8k - 1) + 2(7k - 2) = 4(k + 1) \Rightarrow 22k - 5 = 4k + 4 \Rightarrow 18k = 9 \Rightarrow k = \dfrac{1}{2}`]), w304b = A([secLine(a304, b304, 1, 2, 0), secLine(a304, b304, 1, 2, 1), r`2 + 2 \times 1 = 4`]);
Q('s304', mk.short({ marks: 3, stem: r`The line $x + 2y = 4$ crosses the segment joining $A(-1, -2)$ and $B(8, 7)$ at $P$. Calculate $AP : PB$ and the coordinates of $P$.`, model: J([r`Let $AP : PB = k : 1$, so $P$ is $\left(\dfrac{8k - 1}{k + 1}, \dfrac{7k - 2}{k + 1}\right)$.`, r`$P$ lies on the line: ${w304.md[0]}, so $AP : PB = 1 : 2$.`, r`$x = ${w304b.lines[0]}$ and $y = ${w304b.lines[1]}$, so $P$ is $(2, 1)$. Check: ${w304b.md[2]}.`]), sol: r`Write the division point in terms of $k$, substitute it into the equation of the line, and solve for $k$.`, scheme: [['equation in k', 1], ['AP : PB = 1 : 2', 1], ['P(2, 1)', 1]], d: 3, c: 'application', t: [1], time: 210 }), (C) => { w304.verify(C); w304b.verify(C); const cut = lineCut(a304, b304, [1, 2, 4]); C.assert(rt(cut.r) === '1 : 2' && is(cut.P, [2, 1]), '1 : 2 at (2, 1)'); C.model(['1 : 2', ct(cut.P)]); });

const v305 = [p(3, -4), p(-1, -3), p(-6, 2)], m305 = mid(v305[0], v305[2]), d305 = otherEnd(v305[1], m305), w305 = A([midLine(v305[0], v305[2], 0), midLine(v305[0], v305[2], 1), endLine(v305[1], m305, 0), endLine(v305[1], m305, 1)]);
Q('s305', mk.short({ marks: 3, stem: r`$A(3, -4)$, $B(-1, -3)$ and $C(-6, 2)$ are three consecutive vertices of parallelogram $ABCD$. Find the point where the diagonals cross, and the vertex $D$.`, model: J([r`The diagonals of a parallelogram bisect each other, so they cross at the mid-point $M$ of $AC$: ${w305.md[0]} and ${w305.md[1]}, so $M$ is $${ct(m305)}$.`, r`$M$ is also the mid-point of $BD$, so $D$ has coordinates ${w305.md[2]} and ${w305.md[3]}.`, r`So $D$ is $${ct(d305)}$.`]), sol: r`Use the fact that the diagonals of a parallelogram have the same mid-point.`, scheme: [['M(−3/2, −1)', 1], ['D: method', 1], ['D(−2, 1)', 1]], d: 2, c: 'application', t: [2], time: 180 }), (C) => { w305.verify(C); C.assert(same(d305, fourthVertex(...v305)) && is(d305, [-2, 1]), 'D(−2, 1)'); C.model([ct(m305), ct(d305)]); });

// =============================================================== short answer, 4 marks
const a401 = p(-2, 4), b401 = p(6, -8), P401 = section(a401, b401, 1, 3), M401 = mid(a401, b401);
const w401 = A([secLine(a401, b401, 1, 3, 0), secLine(a401, b401, 1, 3, 1), midLine(a401, b401, 0), midLine(a401, b401, 1), midLine(a401, M401, 0), midLine(a401, M401, 1)]);
Q('s401', mk.short({ marks: 4, stem: r`$A(-2, 4)$ and $B(6, -8)$ are given.
(i) Find the point $P$ on $AB$ such that $AP$ is one-quarter of $AB$.
(ii) Find the mid-point $M$ of $AB$.
(iii) Show that $P$ is the mid-point of $AM$.`, model: J([r`(i) $AP$ is $1$ part of $4$, so $AP : PB = 1 : 3$. $x = ${w401.lines[0]}$ and $y = ${w401.lines[1]}$, so $P$ is $${ct(P401)}$.`, r`(ii) ${w401.md[2]} and ${w401.md[3]}, so $M$ is $${ct(M401)}$.`, r`(iii) Mid-point of $AM$: ${w401.md[4]} and ${w401.md[5]}, which is $P$.`]), sol: r`One-quarter of the way along means the ratio $1 : 3$, not $1 : 4$.`, scheme: [['AP : PB = 1 : 3', 1], ['P(0, 1)', 1], ['M(2, −2)', 1], ['mid-point of AM is P', 1]], d: 2, c: 'application', t: [1, 2], time: 240 }), (C) => { w401.verify(C); C.assert(same(mid(a401, M401), P401) && dist2(a401, P401).mul(16).eq(dist2(a401, b401)), 'P mid-point of AM; AP = AB/4'); C.model(['1 : 3', ct(P401), ct(M401)]); });

const a402 = p(-2, 3), b402 = p(4, -6), w402 = K(F(1, 2), [r`\dfrac{-6k + 3}{k + 1} = 0 \Rightarrow 6k = 3 \Rightarrow k = \dfrac{1}{2}`, r`\dfrac{4k + (-2)}{k + 1} = 0 \Rightarrow 4k = 2 \Rightarrow k = \dfrac{1}{2}`]);
Q('s402', mk.short({ marks: 4, stem: r`For the points $A(-2, 3)$ and $B(4, -6)$:
(i) find the ratio in which the $x$-axis divides $AB$;
(ii) find the ratio in which the $y$-axis divides $AB$;
(iii) explain why the two answers are the same.`, model: J([r`(i) On the $x$-axis $y = 0$. With the ratio $k : 1$: ${w402.md[0]}. The ratio is $1 : 2$, and the point is $(0, 0)$.`, r`(ii) On the $y$-axis $x = 0$: ${w402.md[1]}. The ratio is again $1 : 2$, and the point is again $(0, 0)$.`, r`(iii) Both axes meet $AB$ at the same point, the origin $O$: the segment $AB$ passes through $O$. The two axes therefore cut $AB$ at one and the same point, so they must divide it in the same ratio $AO : OB = 1 : 2$.`]), sol: r`Find each ratio from the coordinate that is zero on that axis; then compare the two points of division.`, scheme: [['(i) 1 : 2', 1], ['(ii) 1 : 2', 1], ['both meet AB at the origin', 1], ['same point, so same ratio', 1]], d: 4, c: 'analysis', t: [1], time: 240 }), (C) => { w402.verify(C); const x = axisCut(a402, b402, 'x'), y = axisCut(a402, b402, 'y'); C.assert(rt(x.r) === '1 : 2' && rt(y.r) === '1 : 2' && is(x.P, [0, 0]) && same(x.P, y.P), 'both 1 : 2 at O'); C.model(['1 : 2', '(0, 0)']); });

const w403 = W(solvectx(['a', 'b'], { a: 4, b: 1 }), [r`\dfrac{a + 5 + (-3)}{3} = 2 \Rightarrow a + 2 = 6 \Rightarrow a = 4`, r`\dfrac{4 + b + (-2)}{3} = 1 \Rightarrow b + 2 = 3 \Rightarrow b = 1`]);
const v403 = [p(4, 4), p(5, 1), p(-3, -2)], g403 = p(2, 1), d403 = mid(v403[1], v403[2]), w403b = A([midLine(v403[1], v403[2], 0), midLine(v403[1], v403[2], 1), secLine(v403[0], d403, 2, 1, 0), secLine(v403[0], d403, 2, 1, 1)]);
Q('s403', mk.short({ marks: 4, stem: r`The centroid of triangle $PQR$ is $G(2, 1)$, where $P$ is $(a, 4)$, $Q$ is $(5, b)$ and $R$ is $(-3, -2)$.
(i) Find $a$ and $b$.
(ii) Find the mid-point $D$ of $QR$.
(iii) Show that $G$ lies on $PD$ with $PG : GD = 2 : 1$.`, model: J([r`(i) ${w403.md[0]}; ${w403.md[1]}. So $P$ is $(4, 4)$ and $Q$ is $(5, 1)$.`, r`(ii) ${w403b.md[0]} and ${w403b.md[1]}, so $D$ is $${ct(d403)}$.`, r`(iii) The point dividing $PD$ in the ratio $2 : 1$ has $x = ${w403b.lines[2]}$ and $y = ${w403b.lines[3]}$. This is $G(2, 1)$, so $G$ lies on $PD$ with $PG : GD = 2 : 1$.`]), sol: r`Write each coordinate of the centroid as an average of the vertices; the median from $P$ ends at the mid-point of $QR$.`, scheme: [['a = 4', 1], ['b = 1', 1], ['D(1, −1/2)', 1], ['2 : 1 point of PD is G', 1]], d: 3, c: 'application', t: [2, 3], time: 240 }), (C) => { w403.verify(C); w403b.verify(C); C.assert(same(centroid(...v403), g403) && same(section(v403[0], d403, 2, 1), g403), 'G is the centroid and the 2 : 1 point'); C.model([4, 1, ct(d403)]); });

const w404 = W(solvectx(['p', 'q'], { p: 3, q: 5 }), [r`\dfrac{(2p - 5) + 7}{2} = 4 \Rightarrow 2p + 2 = 8 \Rightarrow p = 3`, r`\dfrac{-3 + q}{2} = 1 \Rightarrow q - 3 = 2 \Rightarrow q = 5`]);
const a404 = p(1, -3), b404 = p(7, 5), cut404 = axisCut(a404, b404, 'x'), w404b = A([r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`, secLine(a404, b404, 3, 5, 0)]), w404c = K(F(3, 5), [r`\dfrac{5k + (-3)}{k + 1} = 0 \Rightarrow 5k = 3 \Rightarrow k = \dfrac{3}{5}`]);
Q('s404', mk.short({ marks: 4, stem: r`$M(4, 1)$ is the mid-point of the segment with ends $A(2p - 5, -3)$ and $B(7, q)$.
(i) Find $p$ and $q$.
(ii) Find the length of $AB$.
(iii) Find where $AB$ crosses the $x$-axis.`, model: J([r`(i) ${w404.md[0]}; ${w404.md[1]}. So $A$ is $(1, -3)$ and $B$ is $(7, 5)$.`, r`(ii) $AB = ${w404b.lines[0]}$ units.`, r`(iii) On the $x$-axis $y = 0$. With the ratio $k : 1$: ${w404c.md[0]}, so the ratio is $3 : 5$. Then $x = ${w404b.lines[1]}$, and $AB$ crosses the $x$-axis at $${ct(cut404.P)}$.`]), sol: r`Find $p$ and $q$ from the mid-point, then work with the actual end points.`, scheme: [['p = 3 and q = 5', 1], ['AB = 10 units', 1], ['ratio 3 : 5', 1], ['(13/4, 0)', 1]], d: 3, c: 'application', t: [1, 2], time: 240 }), (C) => { w404.verify(C); w404b.verify(C); w404c.verify(C); C.assert(is(mid(p(2 * 3 - 5, -3), p(7, 5)), [4, 1]) && dist(a404, b404).eq(10) && rt(cut404.r) === '3 : 5', 'p, q, AB, ratio'); C.model([3, 5, 10, ct(cut404.P)]); });

const a405 = p(-1, 5), b405 = p(9, -5), cut405 = lineCut(a405, b405, [1, -1, 0]), m405 = mid(a405, b405);
const w405 = K(F(3, 7), [r`9k - 1 = -5k + 5 \Rightarrow 14k = 6 \Rightarrow k = \dfrac{3}{7}`]), w405b = A([secLine(a405, b405, 3, 7, 0), secLine(a405, b405, 3, 7, 1), midLine(a405, b405, 0), midLine(a405, b405, 1), r`4 \ne 0`]);
Q('s405', mk.short({ marks: 4, stem: r`The line $y = x$ cuts the segment joining $A(-1, 5)$ and $B(9, -5)$ at $P$.
(i) Find $AP : PB$.
(ii) Find the coordinates of $P$.
(iii) Find the mid-point of $AB$ and state whether it lies on the line $y = x$.`, model: J([r`(i) Let $AP : PB = k : 1$, so $P$ is $\left(\dfrac{9k - 1}{k + 1}, \dfrac{-5k + 5}{k + 1}\right)$. On $y = x$ the two coordinates are equal: ${w405.md[0]}. So $AP : PB = 3 : 7$.`, r`(ii) $x = ${w405b.lines[0]}$ and $y = ${w405b.lines[1]}$, so $P$ is $${ct(cut405.P)}$.`, r`(iii) ${w405b.md[2]} and ${w405b.md[3]}: the mid-point is $${ct(m405)}$. Its coordinates are not equal (${w405b.md[4]}), so it does not lie on $y = x$.`]), sol: r`A point lies on $y = x$ exactly when its two coordinates are equal.`, scheme: [['equation 9k − 1 = −5k + 5', 1], ['AP : PB = 3 : 7', 1], ['P(2, 2)', 1], ['mid-point (4, 0), not on y = x', 1]], d: 3, c: 'application', t: [1, 2], time: 240 }), (C) => { w405.verify(C); w405b.verify(C); C.assert(rt(cut405.r) === '3 : 7' && is(cut405.P, [2, 2]) && is(m405, [4, 0]) && !m405[0].eq(m405[1]), 'ratio, P, mid-point off the line'); C.model(['3 : 7', ct(cut405.P), ct(m405)]); });

const d406 = p(3, 1), e406 = p(-1, 4), f406 = p(1, -2), [A406, B406, C406] = fromMidpoints(d406, e406, f406);
const n406 = mid(e406, f406), k406 = mid(d406, f406), l406 = mid(d406, e406);
const w406 = A([midLine(e406, f406, 0), midLine(e406, f406, 1), endLine(d406, n406, 0), endLine(d406, n406, 1), endLine(e406, k406, 0), endLine(e406, k406, 1), endLine(f406, l406, 0), endLine(f406, l406, 1), centLine(A406, B406, C406, 0), centLine(A406, B406, C406, 1), centLine(d406, e406, f406, 0), centLine(d406, e406, f406, 1)]);
Q('s406', mk.short({ marks: 4, stem: r`The mid-points of the sides $BC$, $CA$ and $AB$ of triangle $ABC$ are $D(3, 1)$, $E(-1, 4)$ and $F(1, -2)$.
(i) Explain why $AFDE$ is a parallelogram, and use it to find $A$.
(ii) Find $B$ and $C$ in the same way.
(iii) Show that triangles $ABC$ and $DEF$ have the same centroid.`, model: J([r`(i) By the mid-point theorem $FD$ is parallel to $AC$ and half as long, so $FD$ is parallel and equal to $AE$; hence $AFDE$ is a parallelogram. Its diagonals $AD$ and $EF$ bisect each other. The mid-point of $EF$ is $${ct(n406)}$ (${w406.md[0]}, ${w406.md[1]}), so $A$ has coordinates ${w406.md[2]} and ${w406.md[3]}: $A${ct(A406)}$.`, r`(ii) In parallelogram $BDEF$ the mid-point of $DF$ is $${ct(k406)}$, so $B$: ${w406.md[4]} and ${w406.md[5]}, giving $B${ct(B406)}$. In parallelogram $CEFD$ the mid-point of $DE$ is $${ct(l406)}$, so $C$: ${w406.md[6]} and ${w406.md[7]}, giving $C${ct(C406)}$.`, r`(iii) Centroid of $ABC$: ${w406.md[8]} and ${w406.md[9]}. Centroid of $DEF$: ${w406.md[10]} and ${w406.md[11]}. Both are $(1, 1)$.`]), sol: r`Each vertex is the fourth corner of a parallelogram formed with three mid-points, because the diagonals of a parallelogram bisect each other.`, scheme: [['A(−3, 1) with reason', 1], ['B(5, −5)', 1], ['C(1, 7)', 1], ['both centroids (1, 1)', 1]], d: 4, c: 'analysis', t: [2, 3], time: 300 }), (C) => { w406.verify(C); C.assert(is(A406, [-3, 1]) && is(B406, [5, -5]) && is(C406, [1, 7]) && same(fourthVertex(A406, f406, d406), e406), 'vertices; AFDE parallelogram'); C.model([ct(A406), ct(B406), ct(C406), '(1, 1)']); });

// =============================================================== long, 10 marks
const a1 = p(-6, 7), b1 = p(9, -3), P1 = section(a1, b1, 2, 3), cut1 = axisCut(a1, b1, 'x'), M1 = mid(a1, b1);
const wl1 = A([secLine(a1, b1, 2, 3, 0), secLine(a1, b1, 2, 3, 1), secLine(a1, b1, 7, 3, 0), midLine(a1, b1, 0), midLine(a1, b1, 1), r`\dfrac{3}{2} - 0 = \dfrac{3}{2}`, r`\dfrac{9}{2} - \dfrac{3}{2} = 3`]), wl1k = K(F(7, 3), [r`\dfrac{-3k + 7}{k + 1} = 0 \Rightarrow 3k = 7 \Rightarrow k = \dfrac{7}{3}`]);
Q('l01', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) $A(-6, 7)$ and $B(9, -3)$ are given. Find the point $P$ that divides $AB$ in the ratio $2 : 3$, and name the axis on which $P$ lies.
(b) The $x$-axis meets $AB$ at $R$. Find $AR : RB$ and the coordinates of $R$.
(c) Find the mid-point $M$ of $AB$. Show that $M$ lies between $P$ and $R$, and find $PM : MR$.`, model: J([r`**(a)** $x = ${wl1.lines[0]}$ and $y = ${wl1.lines[1]}$. So $P$ is $${ct(P1)}$; its $x$-coordinate is $0$, so $P$ lies on the $y$-axis.`, r`**(b)** On the $x$-axis $y = 0$. With $AR : RB = k : 1$: ${wl1k.md[0]}, so $AR : RB = 7 : 3$. Then $x = ${wl1.lines[2]}$, and $R$ is $${ct(cut1.P)}$.`, r`**(c)** $M$: ${wl1.md[3]} and ${wl1.md[4]}, so $M$ is $${ct(M1)}$. $P$, $M$ and $R$ all lie on $AB$, and their $x$-coordinates $0$, $\dfrac{3}{2}$, $\dfrac{9}{2}$ are in increasing order, so $M$ lies between $P$ and $R$. Along the line the distances are proportional to the changes in $x$: ${wl1.md[5]} and ${wl1.md[6]}, so $PM : MR = \dfrac{3}{2} : 3 = 1 : 2$.`]), sol: 'Use the section formula for P; set y = 0 for the x-axis; for points on one line, ratios of lengths equal ratios of the changes in x.', scheme: [['(a) P(0, 3)', 2], ['(a) on the y-axis', 1], ['(b) equation in k', 1], ['(b) AR : RB = 7 : 3', 1], ['(b) R(9/2, 0)', 1], ['(c) M(3/2, 2)', 1], ['(c) M between P and R', 1], ['(c) PM : MR = 1 : 2', 2]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => { wl1.verify(C); wl1k.verify(C); C.assert(is(P1, [0, 3]) && rt(cut1.r) === '7 : 3' && is(cut1.P, [[9, 2], 0]) && is(M1, [[3, 2], 2]), 'P, R, M'); C.assert(between(P1, cut1.P, M1) && rt(ratioOf(P1, cut1.P, M1)) === '1 : 2', 'M between P and R, 1 : 2'); C.model([ct(P1), '7 : 3', ct(cut1.P), ct(M1), '1 : 2']); });

const a2 = p(7, 7), b2 = p(-7, -3), g2 = p(1, -1), c2 = thirdVertex(a2, b2, g2), d2 = mid(b2, c2);
const wl2 = A([thirdLine(a2, b2, g2, 0), thirdLine(a2, b2, g2, 1), midLine(b2, c2, 0), midLine(b2, c2, 1), r`\sqrt{9^2 + 12^2} = \sqrt{225} = 15`, secLine(a2, d2, 2, 1, 0), secLine(a2, d2, 2, 1, 1), r`\dfrac{2}{3} \times 15 = 10`, r`\sqrt{6^2 + 8^2} = \sqrt{100} = 10`]);
Q('l02', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The medians of triangle $ABC$ meet at $G(1, -1)$. The vertices $A$ and $B$ are $(7, 7)$ and $(-7, -3)$. Find $C$.
(b) Find the mid-point $D$ of $BC$ and the length of the median $AD$.
(c) Show that $G$ lies on $AD$ with $AG : GD = 2 : 1$, and find the length $AG$.`, model: J([r`**(a)** The medians meet at the centroid, so three times each coordinate of $G$ is the sum of that coordinate over the three vertices: ${wl2.md[0]} and ${wl2.md[1]}. So $C$ is $${ct(c2)}$.`, r`**(b)** ${wl2.md[2]} and ${wl2.md[3]}, so $D$ is $${ct(d2)}$. $AD = ${wl2.lines[4]}$ units.`, r`**(c)** The point dividing $AD$ in the ratio $2 : 1$ has $x = ${wl2.lines[5]}$ and $y = ${wl2.lines[6]}$: it is $G(1, -1)$. So $G$ lies on $AD$ with $AG : GD = 2 : 1$, and $AG = ${wl2.lines[7]}$ units. (Check: $AG = ${wl2.lines[8]}$.)`]), sol: 'Three times the centroid is the sum of the vertices; the centroid is the 2 : 1 point of each median, so AG is two-thirds of AD.', scheme: [['(a) method: sum of vertices = 3G', 1], ['(a) C(3, −7)', 2], ['(b) D(−2, −5)', 1], ['(b) AD = 15 units', 2], ['(c) 2 : 1 point of AD', 2], ['(c) it is G', 1], ['(c) AG = 10 units', 1]], d: 3, c: 'application', t: [2, 3], time: 600 }), (C) => { wl2.verify(C); C.assert(is(c2, [3, -7]) && is(d2, [-2, -5]) && dist(a2, d2).eq(15) && same(section(a2, d2, 2, 1), g2) && dist(a2, g2).eq(10), 'C, D, AD, G, AG'); C.model([ct(c2), ct(d2), 15, 10]); });

const a3l = p(-3, -2), b3l = p(5, -4), c3l = p(7, 3), m3l = mid(a3l, c3l), d3l = otherEnd(b3l, m3l), g1 = centroid(a3l, b3l, c3l), g2l = centroid(a3l, c3l, d3l);
const wl3 = A([midLine(a3l, c3l, 0), midLine(a3l, c3l, 1), endLine(b3l, m3l, 0), endLine(b3l, m3l, 1), centLine(a3l, b3l, c3l, 0), centLine(a3l, b3l, c3l, 1), centLine(a3l, c3l, d3l, 0), centLine(a3l, c3l, d3l, 1), secLine(b3l, d3l, 1, 2, 0), secLine(b3l, d3l, 1, 2, 1), secLine(b3l, d3l, 2, 1, 0), secLine(b3l, d3l, 2, 1, 1)]);
Q('l03', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) $A(-3, -2)$, $B(5, -4)$ and $C(7, 3)$ are three vertices of parallelogram $ABCD$, taken in order. Find the point $M$ where the diagonals meet, and the fourth vertex $D$.
(b) Find the centroid $G_1$ of triangle $ABC$ and the centroid $G_2$ of triangle $ACD$.
(c) Show that $G_1$ and $G_2$ lie on the diagonal $BD$ and cut it into three equal parts.`, model: J([r`**(a)** The diagonals bisect each other, so $M$ is the mid-point of $AC$: ${wl3.md[0]} and ${wl3.md[1]}, so $M$ is $${ct(m3l)}$. $M$ is also the mid-point of $BD$: ${wl3.md[2]} and ${wl3.md[3]}, so $D$ is $${ct(d3l)}$.`, r`**(b)** $G_1$: ${wl3.md[4]} and ${wl3.md[5]}, so $G_1$ is $${ct(g1)}$. $G_2$: ${wl3.md[6]} and ${wl3.md[7]}, so $G_2$ is $${ct(g2l)}$.`, r`**(c)** The points of trisection of $BD$ divide it in the ratios $1 : 2$ and $2 : 1$. Ratio $1 : 2$: $x = ${wl3.lines[8]}$ and $y = ${wl3.lines[9]}$, which is $G_1$. Ratio $2 : 1$: $x = ${wl3.lines[10]}$ and $y = ${wl3.lines[11]}$, which is $G_2$. So $G_1$ and $G_2$ lie on $BD$ and $BG_1 = G_1G_2 = G_2D$.`]), sol: 'The diagonals of a parallelogram share their mid-point; compare each centroid with the two points of trisection of BD.', scheme: [['(a) M(2, 1/2)', 1], ['(a) D(−1, 5)', 2], ['(b) G₁(3, −1)', 1], ['(b) G₂(1, 2)', 2], ['(c) 1 : 2 point of BD is G₁', 2], ['(c) 2 : 1 point of BD is G₂', 1], ['(c) three equal parts', 1]], d: 4, c: 'analysis', t: [1, 2, 3], time: 600 }), (C) => { wl3.verify(C); C.assert(same(d3l, fourthVertex(a3l, b3l, c3l)) && is(d3l, [-1, 5]) && same(section(b3l, d3l, 1, 2), g1) && same(section(b3l, d3l, 2, 1), g2l) && dist2(b3l, g1).eq(dist2(g1, g2l)) && dist2(g1, g2l).eq(dist2(g2l, d3l)), 'D; G1, G2 trisect BD'); C.model([ct(m3l), ct(d3l), ct(g1), ct(g2l)]); });

const a4 = p(5, -3), b4 = p(-1, 6), cx4 = axisCut(a4, b4, 'x'), cy4 = axisCut(a4, b4, 'y'), R4 = section(a4, b4, 2, 1);
const wl4 = A([secLine(a4, b4, 1, 2, 0), secLine(a4, b4, 5, 1, 1), secLine(a4, b4, 2, 1, 0), secLine(a4, b4, 2, 1, 1), midLine(cx4.P, b4, 0), midLine(cx4.P, b4, 1)]), wl4a = K(F(1, 2), [r`\dfrac{6k + (-3)}{k + 1} = 0 \Rightarrow 6k = 3 \Rightarrow k = \dfrac{1}{2}`]), wl4b = K(5, [r`\dfrac{-k + 5}{k + 1} = 0 \Rightarrow k = 5`]);
Q('l04', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The $x$-axis meets the segment from $A(5, -3)$ to $B(-1, 6)$ at $P$. Calculate $AP : PB$ and the coordinates of $P$.
(b) The $y$-axis meets $AB$ at $Q$. Calculate $AQ : QB$ and the coordinates of $Q$.
(c) Show that $P$ is a point of trisection of $AB$, and find the other point of trisection $R$.`, model: J([r`**(a)** On the $x$-axis $y = 0$. With $AP : PB = k : 1$: ${wl4a.md[0]}, so $AP : PB = 1 : 2$. Then $x = ${wl4.lines[0]}$, and $P$ is $${ct(cx4.P)}$.`, r`**(b)** On the $y$-axis $x = 0$: ${wl4b.md[0]}, so $AQ : QB = 5 : 1$. Then $y = ${wl4.lines[1]}$, and $Q$ is $${ct(cy4.P)}$.`, r`**(c)** $AP : PB = 1 : 2$ means $AP$ is one-third of $AB$, so $P$ is the point of trisection nearer to $A$. The other point $R$ divides $AB$ in the ratio $2 : 1$: $x = ${wl4.lines[2]}$ and $y = ${wl4.lines[3]}$, so $R$ is $${ct(R4)}$. (Check: $R$ is the mid-point of $PB$, since ${wl4.md[4]} and ${wl4.md[5]}.)`]), sol: 'Set the coordinate that is zero on each axis; a ratio of 1 : 2 means one-third of the way along.', scheme: [['(a) AP : PB = 1 : 2', 2], ['(a) P(3, 0)', 1], ['(b) AQ : QB = 5 : 1', 1], ['(b) Q(0, 9/2)', 2], ['(c) P is a point of trisection, with reason', 2], ['(c) R(1, 3)', 2]], d: 3, c: 'application', t: [1], time: 600 }), (C) => { wl4.verify(C); wl4a.verify(C); wl4b.verify(C); C.assert(rt(cx4.r) === '1 : 2' && is(cx4.P, [3, 0]) && rt(cy4.r) === '5 : 1' && is(cy4.P, [0, [9, 2]]) && is(R4, [1, 3]) && same(mid(cx4.P, b4), R4), 'P, Q, R'); C.model(['1 : 2', ct(cx4.P), '5 : 1', ct(cy4.P), ct(R4)]); });

const a5l = p(-5, 8), b5l = p(7, -4), P5 = section(a5l, b5l, 1, 2), c5l = p(3, 1), d5l = p(-5, 7), R5 = section(c5l, d5l, 1, 3);
const wl5 = A([secLine(a5l, b5l, 1, 2, 0), secLine(a5l, b5l, 1, 2, 1), r`\sqrt{8^2 + 6^2} = \sqrt{100} = 10`, secLine(c5l, d5l, 1, 3, 0), secLine(c5l, d5l, 1, 3, 1), midLine(c5l, P5, 0), midLine(c5l, P5, 1)]), wl5b = W(solvectx(['h', 'k'], { h: 2, k: 3 }), [r`\dfrac{(2h - 1) + (-5)}{2} = -1 \Rightarrow 2h - 6 = -2 \Rightarrow h = 2`, r`\dfrac{1 + (3k - 2)}{2} = 4 \Rightarrow 3k - 1 = 8 \Rightarrow k = 3`]);
Q('l05', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) Find the point $P$ that divides the join of $A(-5, 8)$ and $B(7, -4)$ in the ratio $1 : 2$.
(b) $P$ is also the mid-point of the segment joining $C(2h - 1, 1)$ and $D(-5, 3k - 2)$. Find $h$ and $k$, and write down $C$ and $D$.
(c) Find the length $CD$, and show that the point $R$ with $CR : RD = 1 : 3$ is the mid-point of $CP$.`, model: J([r`**(a)** $x = ${wl5.lines[0]}$ and $y = ${wl5.lines[1]}$, so $P$ is $${ct(P5)}$.`, r`**(b)** ${wl5b.md[0]}; ${wl5b.md[1]}. So $C$ is $${ct(c5l)}$ and $D$ is $${ct(d5l)}$.`, r`**(c)** $CD = ${wl5.lines[2]}$ units. $R$: $x = ${wl5.lines[3]}$ and $y = ${wl5.lines[4]}$, so $R$ is $${ct(R5)}$. Mid-point of $CP$: ${wl5.md[5]} and ${wl5.md[6]}, which is $R$.`]), sol: 'Section formula for P; equate the mid-point coordinates of CD with those of P; CR : RD = 1 : 3 puts R halfway from C to the mid-point P of CD.', scheme: [['(a) P(−1, 4)', 3], ['(b) h = 2', 1], ['(b) k = 3', 1], ['(b) C(3, 1) and D(−5, 7)', 1], ['(c) CD = 10 units', 1], ['(c) R(1, 5/2)', 2], ['(c) R is the mid-point of CP', 1]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => { wl5.verify(C); wl5b.verify(C); C.assert(same(mid(c5l, d5l), P5) && is(P5, [-1, 4]) && same(mid(c5l, P5), R5) && dist(c5l, d5l).eq(10) && is(c5l, [2 * 2 - 1, 1]) && is(d5l, [-5, 3 * 3 - 2]), 'P, C, D, R'); C.model([ct(P5), ct(c5l), ct(d5l), 10, ct(R5)]); });

const v6l = [p(-4, -2), p(8, -2), p(2, 10)], G6 = centroid(...v6l), D6 = mid(v6l[0], v6l[1]), E6 = mid(v6l[1], v6l[2]), cut6 = axisCut(v6l[0], E6, 'y');
const wl6 = A([centLine(...v6l, 0), centLine(...v6l, 1), midLine(v6l[0], v6l[1], 0), midLine(v6l[0], v6l[1], 1), r`10 - (-2) = 12`, r`12 \times 10 = 120`, r`10 - 2 = 8`, r`\dfrac{2}{3} \times 12 = 8`, midLine(v6l[1], v6l[2], 0), midLine(v6l[1], v6l[2], 1), secLine(v6l[0], E6, 2, 1, 0), secLine(v6l[0], E6, 2, 1, 1), secLine(v6l[0], E6, 4, 5, 1)]), wl6k = K(F(4, 5), [r`\dfrac{5k + (-4)}{k + 1} = 0 \Rightarrow 5k = 4 \Rightarrow k = \dfrac{4}{5}`]);
Q('l06', mk.long({ marks: 10, stem: r`A triangular park in Navrang Nagar (an imagined town) is drawn on a grid in which $1$ unit stands for $10$ m. Its corners are $A(-4, -2)$, $B(8, -2)$ and $C(2, 10)$.
(a) A fountain is to be placed at the centroid $G$ of the park. Find $G$.
(b) A gate stands at the mid-point $D$ of $AB$. Find $D$, find the length of the straight path $CD$ in metres, and show that $CG$ is two-thirds of $CD$.
(c) A second straight path runs from $A$ to the mid-point $E$ of $BC$. Find $E$, show that this path passes through $G$, and find where it crosses the $y$-axis.`, model: J([r`**(a)** ${wl6.md[0]} and ${wl6.md[1]}, so the fountain is at $G${ct(G6)}$.`, r`**(b)** ${wl6.md[2]} and ${wl6.md[3]}, so $D$ is $${ct(D6)}$. $C$ and $D$ have the same $x$-coordinate, so $CD = ${wl6.lines[4]}$ units, that is ${wl6.md[5]} m. Also $CG = ${wl6.lines[6]}$ units and ${wl6.md[7]}, so $CG$ is two-thirds of $CD$.`, r`**(c)** ${wl6.md[8]} and ${wl6.md[9]}, so $E$ is $${ct(E6)}$. The point dividing $AE$ in the ratio $2 : 1$ has $x = ${wl6.lines[10]}$ and $y = ${wl6.lines[11]}$, which is $G$; so the path passes through the fountain. On the $y$-axis $x = 0$; with the ratio $k : 1$, ${wl6k.md[0]}, and then $y = ${wl6.lines[12]}$: the path crosses the $y$-axis at $${ct(cut6.P)}$.`]), sol: 'Centroid by averaging the corners; the median CD is vertical; G is the 2 : 1 point of every median; set x = 0 for the y-axis.', scheme: [['(a) G(2, 2)', 3], ['(b) D(2, −2)', 1], ['(b) CD = 120 m', 1], ['(b) CG = 8 = 2/3 of 12', 1], ['(c) E(5, 4)', 1], ['(c) G on AE', 1], ['(c) crossing (0, 2/3)', 2]], d: 2, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { wl6.verify(C); wl6k.verify(C); C.assert(is(G6, [2, 2]) && is(D6, [2, -2]) && dist(v6l[2], D6).eq(12) && dist(v6l[2], G6).eq(8) && same(section(v6l[0], E6, 2, 1), G6) && is(cut6.P, [0, [2, 3]]), 'G, D, CD, CG, E, crossing'); C.model([ct(G6), ct(D6), 120, ct(E6), ct(cut6.P)]); });

const a7 = p(-4, 5), b7 = p(5, -4), c7 = p(2, 8), cut7 = lineCut(a7, b7, [2, 1, 3]), Q7 = section(a7, b7, 1, 2), N7 = mid(a7, b7), G7 = centroid(a7, b7, c7);
const wl7 = A([secLine(a7, b7, 2, 1, 0), secLine(a7, b7, 2, 1, 1), r`2 \times 2 + (-1) = 3`, secLine(a7, b7, 1, 2, 0), secLine(a7, b7, 1, 2, 1), midLine(cut7.P, Q7, 0), midLine(cut7.P, Q7, 1), midLine(a7, b7, 0), midLine(a7, b7, 1), centLine(a7, b7, c7, 0), centLine(a7, b7, c7, 1), secLine(c7, N7, 2, 1, 0), secLine(c7, N7, 2, 1, 1)]), wl7k = K(2, [r`2(5k - 4) + (-4k + 5) = 3(k + 1) \Rightarrow 6k - 3 = 3k + 3 \Rightarrow 3k = 6 \Rightarrow k = 2`]);
Q('l07', mk.long({ marks: 10, stem: r`Answer each part. Show all working.
(a) The line $2x + y = 3$ cuts the segment joining $A(-4, 5)$ and $B(5, -4)$ at $P$. Find $AP : PB$ and the coordinates of $P$.
(b) Show that $P$ is a point of trisection of $AB$. Find the other point of trisection $Q$, and check that $PQ$ and $AB$ have the same mid-point.
(c) $C$ is the point $(2, 8)$. Find the centroid $G$ of triangle $ABC$, and show that $G$ lies on the median from $C$.`, model: J([r`**(a)** Let $AP : PB = k : 1$, so $P$ is $\left(\dfrac{5k - 4}{k + 1}, \dfrac{-4k + 5}{k + 1}\right)$. On the line: ${wl7k.md[0]}. So $AP : PB = 2 : 1$, with $x = ${wl7.lines[0]}$ and $y = ${wl7.lines[1]}$: $P$ is $${ct(cut7.P)}$. Check: ${wl7.md[2]}.`, r`**(b)** $AP : PB = 2 : 1$ means $AP$ is two-thirds of $AB$, so $P$ is the point of trisection nearer to $B$. $Q$ divides $AB$ in the ratio $1 : 2$: $x = ${wl7.lines[3]}$ and $y = ${wl7.lines[4]}$, so $Q$ is $${ct(Q7)}$. Mid-point of $PQ$: ${wl7.md[5]} and ${wl7.md[6]}; mid-point of $AB$: ${wl7.md[7]} and ${wl7.md[8]}. Both are $${ct(N7)}$.`, r`**(c)** ${wl7.md[9]} and ${wl7.md[10]}, so $G$ is $${ct(G7)}$. The median from $C$ ends at the mid-point $N${ct(N7)}$ of $AB$. The point dividing $CN$ in the ratio $2 : 1$ has $x = ${wl7.lines[11]}$ and $y = ${wl7.lines[12]}$, which is $G$; so $G$ lies on the median from $C$.`]), sol: 'Substitute the k : 1 division point into the equation of the line; the two points of trisection are symmetric about the mid-point; the centroid is the 2 : 1 point of the median.', scheme: [['(a) equation in k', 1], ['(a) AP : PB = 2 : 1', 1], ['(a) P(2, −1)', 1], ['(b) P is a point of trisection', 1], ['(b) Q(−1, 2)', 1], ['(b) common mid-point (1/2, 1/2)', 1], ['(c) G(1, 3)', 2], ['(c) G is the 2 : 1 point of CN', 2]], d: 3, c: 'analysis', t: [1, 2, 3], time: 600 }), (C) => { wl7.verify(C); wl7k.verify(C); C.assert(rt(cut7.r) === '2 : 1' && is(cut7.P, [2, -1]) && is(Q7, [-1, 2]) && same(mid(cut7.P, Q7), N7) && is(G7, [1, 3]) && same(section(c7, N7, 2, 1), G7), 'P, Q, mid-points, G'); C.model(['2 : 1', ct(cut7.P), ct(Q7), ct(N7), ct(G7)]); });
